# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# Catch-at-length model of the male-only snow crab data ----
## Setup ----
# data_snow_crab_results holds values from an R version of the GMACS model,
# made by data-raw/data_snow_crab.R.
snow_crab_reference <- function(model, label) {
  dplyr::filter(
    data_snow_crab_results,
    .data[["model"]] == !!model,
    .data[["label"]] == !!label
  ) |>
    dplyr::pull(.data[["value"]])
}
snow_crab_input <- initialize_fims(
  parameters_snow_crab,
  data = FIMSFrame(data_snow_crab)
)
snow_crab_at_gmacs_par <- fit_fims(snow_crab_input, optimize = FALSE)

## IO correctness ----
test_that("catch-at-length model matches the R version of GMACS at the GMACS estimates", {
  report <- get_report(snow_crab_at_gmacs_par)
  #' @description Test that spawning biomass at the GMACS estimates matches the R version of GMACS.
  expect_equal(
    object = report[["spawning_biomass"]][[1]],
    expected = snow_crab_reference("gmacs_par", "spawning_biomass"),
    tolerance = 1e-8
  )
  # Expected catch and survey biomass by fleet and year, in the order of
  # the reference rows.
  fleet_names <- names(snow_crab_input[["model_data"]][["fleets"]])
  report_by_fleet_year <- function(label) {
    reference <- dplyr::filter(
      data_snow_crab_results,
      .data[["model"]] == "gmacs_par",
      .data[["label"]] == !!label
    )
    purrr::map2_dbl(
      reference[["fleet"]], reference[["year"]],
      function(fleet, year) {
        report[[label]][[match(fleet, fleet_names)]][year - 1981]
      }
    )
  }
  #' @description Test that expected survey biomass at the GMACS estimates matches the R version of GMACS.
  expect_equal(
    object = report_by_fleet_year("index_expected"),
    expected = snow_crab_reference("gmacs_par", "index_expected"),
    tolerance = 1e-8
  )
  #' @description Test that expected retained catch at the GMACS estimates matches the R version of GMACS.
  expect_equal(
    object = report_by_fleet_year("catch_retained_expected"),
    expected = snow_crab_reference("gmacs_par", "catch_retained_expected"),
    tolerance = 1e-8
  )
  #' @description Test that expected discarded catch at the GMACS estimates matches the R version of GMACS.
  expect_equal(
    object = report_by_fleet_year("catch_discarded_expected"),
    expected = snow_crab_reference("gmacs_par", "catch_discarded_expected"),
    tolerance = 1e-8
  )
})

test_that("catch-at-length fit matches the fit of the R version of GMACS", {
  # nlminb stops with false convergence at a maximum gradient of about 0.002,
  # so fit_fims() warns. The fit of the R version of GMACS adds Newton steps,
  # which fit_fims() does not have, so the tolerances allow for that gap.
  fit <- suppressWarnings(fit_fims(snow_crab_input, get_sd = FALSE))
  # The 2 objectives differ by a constant: FIMS counts crabs and metric tons
  # where GMACS counts thousands of crabs and 1000 metric tons, which shifts
  # every lognormal density, and FIMS keeps the normalizing constants of the
  # priors and processes. The first recruitment deviation also differs: FIMS
  # gives it the stationary AR1 sd, sd / sqrt(1 - rho^2), and GMACS gives it
  # sd. With rho = 0.01 that changes the objective by about 3e-4 times the
  # squared first deviation. So compare the change from the GMACS estimates
  # to the optimum.
  objective_change <- get_obj(fit)[["fn"]](get_opt(fit)[["par"]]) -
    get_obj(snow_crab_at_gmacs_par)[["fn"]](
      get_obj(snow_crab_at_gmacs_par)[["par"]]
    )
  #' @description Test that the drop in the objective from the GMACS estimates to the optimum matches the R version of GMACS.
  expect_equal(
    object = objective_change,
    expected = snow_crab_reference("fit", "objective") -
      snow_crab_reference("gmacs_par", "objective"),
    tolerance = 1e-6
  )
  #' @description Test that fitted spawning biomass matches the fit of the R version of GMACS.
  expect_equal(
    object = get_report(fit)[["spawning_biomass"]][[1]],
    expected = snow_crab_reference("fit", "spawning_biomass"),
    tolerance = 1e-4
  )
})
